'use strict';

/**
 * site-links.test.js — the skill's ccinternals.dev link map cannot rot.
 *
 * references/site-links.json is generated by site/generator/build.js from
 * references/state/author-facts.json. These are EQUALITY and MEMBERSHIP checks,
 * not counts: the committed file must equal a fresh rebuild through the same
 * function build.js uses, and every slug or URL the skill can print must be a
 * real page slug.
 */

const test = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { execFileSync } = require('child_process');

const SKILL_DIR = path.resolve(__dirname, '..', '..');
const REPO_DIR = path.resolve(SKILL_DIR, '..', '..', '..');
const REFS = path.join(SKILL_DIR, 'references');
const FETCH = path.join(SKILL_DIR, 'scripts', 'fetch-lesson.js');

const { build, factAnchor, buildSiteLinks, serializeSiteLinks, SECTION } =
  require(path.join(REPO_DIR, 'site', 'generator', 'build.js'));
const {
  footerUrls, pickSlugs, lessonFooter, loadSiteLinks, LABEL, MAX_LINKS,
} = require('../site-links.js');
const { lookup, siteFooter } = require('../state.js');

const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const facts = readJson(path.join(REFS, 'state', 'author-facts.json'));
const topicIndex = readJson(path.join(REFS, 'topic-index.json'));
const onDiskText = fs.readFileSync(path.join(REFS, 'site-links.json'), 'utf8');
const onDisk = JSON.parse(onDiskText);
const SLUGS = new Set(facts.pages.map((p) => p.slug));

const fetchLesson = (id) => execFileSync('node', [FETCH, String(id)], { encoding: 'utf8' });

test('site-links.json equals a map rebuilt from author-facts.json (rebuild with build.js)', () => {
  const rebuilt = buildSiteLinks(facts, topicIndex);
  assert.deepStrictEqual(onDisk, rebuilt,
    'site-links.json is stale — run: node site/generator/build.js');
  // Byte-level too, so key order and the trailing newline are pinned.
  assert.strictEqual(onDiskText, serializeSiteLinks(rebuilt));
});

test('base is the absolute /cowork/ section URL', () => {
  assert.strictEqual(onDisk.base, `https://ccinternals.dev/${SECTION}/`);
});

for (const [kind, map] of [['by_lesson', onDisk.by_lesson], ['by_state_page', onDisk.by_state_page]]) {
  for (const [key, pairs] of Object.entries(map)) {
    for (const [slug] of pairs) {
      test(`${kind}[${key}] -> "${slug}" is a real page slug`, () => {
        assert.ok(SLUGS.has(slug), `"${slug}" is not an author-facts.json page slug`);
      });
    }
    test(`${kind}[${key}] weights are citation counts, ordered desc then by slug`, () => {
      const field = kind === 'by_lesson' ? 'lessons' : 'state_page';
      for (const [slug, n] of pairs) {
        const cites = facts.facts.filter((f) => f.page === slug && (field === 'lessons'
          ? (f.sources.lessons || []).includes(Number(key)) : f.sources.state_page === key)).length;
        assert.strictEqual(n, cites, `${slug} should carry ${cites} citations of ${key}`);
      }
      for (let i = 1; i < pairs.length; i++) {
        const [a, na] = pairs[i - 1];
        const [b, nb] = pairs[i];
        assert.ok(na > nb || (na === nb && a < b), `${key}: ${a}:${na} must sort before ${b}:${nb}`);
      }
    });
  }
}

for (const [id, target] of Object.entries(onDisk.by_fact)) {
  test(`by_fact[${id}] targets a real page with the fact's anchor`, () => {
    const [slug, anchor] = target.split('#');
    assert.ok(SLUGS.has(slug), `"${slug}" is not an author-facts.json page slug`);
    const fact = facts.facts.find((f) => f.id === id);
    assert.ok(fact, `by_fact names unknown fact "${id}"`);
    assert.strictEqual(slug, fact.page);
    if (fact.durability === 'volatile') {
      assert.strictEqual(anchor, undefined, 'volatile facts render without a per-fact anchor');
    } else {
      assert.strictEqual(anchor, factAnchor({ id }));
    }
  });
}

test('every by_fact anchor exists as an id in the built page', () => {
  const out = fs.mkdtempSync(path.join(os.tmpdir(), 'site-links-'));
  try {
    build(out);
    for (const target of Object.values(onDisk.by_fact)) {
      const [slug, anchor] = target.split('#');
      if (!anchor) continue;
      const html = fs.readFileSync(path.join(out, SECTION, slug, 'index.html'), 'utf8');
      assert.ok(html.includes(`id="${anchor}"`), `${slug}/index.html has no id="${anchor}"`);
    }
  } finally {
    fs.rmSync(out, { recursive: true, force: true });
  }
});

const SKILL_MD = fs.readFileSync(path.join(SKILL_DIR, 'SKILL.md'), 'utf8');
const SKILL_URLS = [...SKILL_MD.matchAll(/ccinternals\.dev\/cowork\/([^/\s`?#)]*)\/?/g)].map((m) => m[1]);

test('SKILL.md links ccinternals.dev pages at all (positive control for the per-URL checks)', () => {
  assert.ok(SKILL_URLS.filter(Boolean).length >= 10, `found only ${SKILL_URLS.length} /cowork/ URLs in SKILL.md`);
});

test('every concrete ccinternals.dev URL in SKILL.md carries ?ref=skill (the model copies it verbatim)', () => {
  const urls = [...SKILL_MD.matchAll(/https:\/\/ccinternals\.dev\/cowork\/[^\s`)]*/g)].map((m) => m[0])
    .filter((u) => !u.includes('<'));
  assert.ok(urls.length >= 12, `control: found only ${urls.length} concrete URLs`);
  for (const u of urls) assert.ok(u.endsWith('?ref=skill'), `SKILL.md URL without ?ref=skill: ${u}`);
});

for (const slug of new Set(SKILL_URLS)) {
  if (slug === '' || slug === '<slug>') continue; // the hub, and the template placeholder
  test(`SKILL.md URL /cowork/${slug}/ is a real page slug`, () => {
    assert.ok(SLUGS.has(slug), `SKILL.md links /cowork/${slug}/, which is not an author-facts.json page`);
  });
}

test('positive control: lesson 139 maps to deleting-files', () => {
  assert.ok(Object.keys(onDisk.by_lesson).length > 0, 'by_lesson is empty');
  assert.deepStrictEqual((onDisk.by_lesson['139'] || [])[0], ['deleting-files', 6]);
  assert.deepStrictEqual(onDisk.by_state_page['cowork-permissions'], [['deleting-files', 2]]);
});

test('every cited lesson resolves by the id fetch-lesson.js uses, with agreeing lesson_number', () => {
  for (const key of Object.keys(onDisk.by_lesson)) {
    const l = topicIndex.lessons.find((x) => x.id === Number(key));
    assert.ok(l, `site-links cites lesson ${key}, which has no topic-index id ${key}`);
    assert.strictEqual(String(l.lesson_number), key,
      `topic-index id ${key} is lesson_number ${l.lesson_number}: the link would attach to the wrong lesson`);
  }
});

test('a citation whose id and lesson_number disagree fails the build, not links the wrong lesson', () => {
  const doc = { facts: [{ id: 'x.y', page: 'files-and-paths', sources: { lessons: [32] } }] };
  const idx = { lessons: [{ id: 32, lesson_number: '10' }] };
  assert.throws(() => buildSiteLinks(doc, idx), /numberings disagree/);
  assert.throws(() => buildSiteLinks(doc, { lessons: [] }), /no topic-index entry/);
});

const HUB = 'https://ccinternals.dev/cowork/?ref=skill';
const page = (slug) => `https://ccinternals.dev/cowork/${slug}/?ref=skill`;

test('selection rule: dominant page, else a clear top two, else the hub; never more than two', () => {
  const links = { base: 'https://ccinternals.dev/cowork/' };
  assert.deepStrictEqual(footerUrls(links, []), []);
  assert.deepStrictEqual(pickSlugs([['a', 3]]), ['a']);
  assert.deepStrictEqual(pickSlugs([['a', 1], ['b', 1]]), ['a', 'b']);       // two, tied: both
  assert.deepStrictEqual(pickSlugs([['a', 6], ['b', 2]]), ['a']);             // two, 3x: top only
  assert.deepStrictEqual(pickSlugs([['a', 7], ['b', 3], ['c', 1], ['d', 1]]), ['a']);
  assert.deepStrictEqual(pickSlugs([['a', 3], ['b', 2], ['c', 1]]), ['a', 'b']);
  assert.deepStrictEqual(pickSlugs([['a', 2], ['b', 1], ['c', 1], ['d', 1]]), ['index']); // no majority
  assert.deepStrictEqual(pickSlugs([['a', 2], ['b', 1], ['c', 1]]), ['index']);          // 2/4 is not a majority
  assert.deepStrictEqual(pickSlugs([['a', 1], ['b', 1], ['c', 1]]), ['index']);
  // 3+ pages: a majority alone is not enough, the top page must also double the runner-up
  assert.deepStrictEqual(pickSlugs([['a', 5], ['b', 3], ['c', 1]]), ['a', 'b']);
  // top two holding exactly half is not a majority
  assert.deepStrictEqual(pickSlugs([['a', 2], ['b', 2], ['c', 1], ['d', 1], ['e', 1], ['f', 1]]), ['index']);
  // Order of input does not matter; bare slugs weigh 1.
  assert.deepStrictEqual(pickSlugs([['c', 1], ['a', 3], ['b', 2]]), ['a', 'b']);
  assert.deepStrictEqual(footerUrls(links, ['b', 'a', 'a']), [page('a')]);
  assert.deepStrictEqual(footerUrls(links, [['index', 1]]), [HUB]);
  for (const pairs of [...Object.values(onDisk.by_lesson), ...Object.values(onDisk.by_state_page)]) {
    assert.ok(pickSlugs(pairs).length <= MAX_LINKS, JSON.stringify(pairs));
  }
});

test('no base, or a non-URL base, prints no footer rather than "undefined..."', () => {
  assert.deepStrictEqual(footerUrls({}, [['a', 1]]), []);
  assert.deepStrictEqual(footerUrls({ base: 'undefined' }, [['a', 1]]), []);
  for (const body of ['{"by_lesson":{"139":[["deleting-files",6]]}}', '{"base":42}', '{"base":"cowork/"}']) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'site-links-base-'));
    try {
      fs.writeFileSync(path.join(dir, 'site-links.json'), body);
      const saved = process.stderr.write;
      process.stderr.write = () => true;
      let links;
      try { links = loadSiteLinks(dir); } finally { process.stderr.write = saved; }
      assert.strictEqual(links, null, body);
      assert.deepStrictEqual(lessonFooter(links, { id: 139, lesson_number: 139 }).lines, [], body);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  }
});

test('lessonFooter refuses a mapped lesson whose id and lesson_number disagree', () => {
  const links = { base: 'https://ccinternals.dev/cowork/', by_lesson: { 32: [['files-and-paths', 1]] } };
  const bad = lessonFooter(links, { id: 32, lesson_number: '10' });
  assert.deepStrictEqual(bad.lines, []);
  assert.match(bad.error, /numbering mismatch/);
  // Control: the same map prints when the numberings agree (or lesson_number is absent).
  assert.deepStrictEqual(lessonFooter(links, { id: 32, lesson_number: 32 }).lines, [`${LABEL} ${page('files-and-paths')}`]);
  assert.deepStrictEqual(lessonFooter(links, { id: 32 }).lines, [`${LABEL} ${page('files-and-paths')}`]);
});

const footerOf = (id) => fetchLesson(id).split('\n').filter((l) => l.startsWith(LABEL));

for (const [id, slug] of [[116, 'detecting-cowork'], [138, 'delivering-outputs'], [140, 'files-and-paths'],
  [89, 'plugins-and-plugin-root']]) {
  test(`fetch-lesson.js ${id} links its dominant page (${slug}), not the hub`, () => {
    assert.deepStrictEqual(footerOf(id), [`${LABEL} ${page(slug)}`]);
  });
}

test('fetch-lesson.js 122 links its clear top two (files-and-paths, sub-agents)', () => {
  assert.deepStrictEqual(footerOf(122), [`${LABEL} ${page('files-and-paths')}`, `${LABEL} ${page('sub-agents')}`]);
});

test('fetch-lesson.js on a lesson with no dominant page (174) prints only the section hub', () => {
  assert.deepStrictEqual(footerOf(174), [`${LABEL} ${HUB}`]);
});

test('fetch-lesson.js 139 ends with the deleting-files skill-author page', () => {
  const out = fetchLesson(139);
  assert.ok(out.includes(`${LABEL} https://ccinternals.dev/cowork/deleting-files/?ref=skill`), out.slice(-400));
  assert.ok(out.startsWith('# Lesson 139:'), 'the lesson header format must be unchanged');
});

test('fetch-lesson.js on a non-Cowork lesson (Hooks System, id 32) prints no footer', () => {
  const l = topicIndex.lessons.find((x) => x.id === 32);
  assert.match(l.title, /hook/i, 'control: id 32 should still be the hooks lesson');
  assert.ok(!fetchLesson(32).includes(LABEL));
});

test('state.js prints the mapped page for a matched state page, and nothing without a map', () => {
  const r = lookup(REFS, 'cowork-permissions');
  assert.ok(r.pages.length > 0, 'control: the cowork-permissions page should match');
  assert.deepStrictEqual(siteFooter(REFS, r), [`${LABEL} ${page('deleting-files')}`]);
  const empty = fs.mkdtempSync(path.join(os.tmpdir(), 'site-links-none-'));
  try {
    assert.deepStrictEqual(siteFooter(empty, r), []);
  } finally {
    fs.rmSync(empty, { recursive: true, force: true });
  }
});

// Registry entries inherit no page through their provenance lessons: L108 alone is
// the provenance of dozens of env-catalog / control-protocol entries.
for (const q of ['proto.get_session_cost', 'env.CLAUDE_UPDATER_TOKEN', 'compact', 'effort']) {
  test(`state.js ${q} prints no skill-author page (registry entries only)`, () => {
    const r = lookup(REFS, q);
    assert.ok(r.entries.length > 0, `control: "${q}" should match registry entries`);
    assert.strictEqual(r.pages.length, 0, `control: "${q}" should match no state page`);
    assert.deepStrictEqual(siteFooter(REFS, r), []);
  });
}

test('state.js hooks prints only the dominant page of plugins-skills-hooks (no asking-the-user)', () => {
  const r = lookup(REFS, 'hooks');
  assert.ok(r.pages.some((p) => p.domain === 'plugins-skills-hooks'), 'control: the state page should match');
  assert.deepStrictEqual(siteFooter(REFS, r), [`${LABEL} ${page('plugins-and-plugin-root')}`]);
});

test('state.js never reads by_lesson: a map linking every provenance lesson still prints nothing for entries', () => {
  const r = lookup(REFS, 'proto.get_session_cost');
  const lessons = new Set(r.entries.flatMap((e) => (e.provenance || []).map((p) => p.lesson)));
  assert.ok(lessons.size > 0, 'control: the entry should carry provenance lessons');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'site-links-prov-'));
  try {
    const by_lesson = Object.fromEntries([...lessons].map((n) => [String(n), [['shell-commands', 9]]]));
    fs.writeFileSync(path.join(dir, 'site-links.json'),
      JSON.stringify({ base: 'https://ccinternals.dev/cowork/', by_lesson, by_state_page: {}, by_fact: {} }));
    assert.deepStrictEqual(siteFooter(dir, r), []);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test('build.js --out <dir> leaves the tracked site-links.json untouched', () => {
  const tracked = path.join(REFS, 'site-links.json');
  const before = fs.statSync(tracked).mtimeMs;
  const out = fs.mkdtempSync(path.join(os.tmpdir(), 'site-links-out-'));
  try {
    const log = execFileSync('node', [path.join(REPO_DIR, 'site', 'generator', 'build.js'), '--out', out],
      { encoding: 'utf8' });
    assert.ok(!/site-links:/.test(log), 'an --out build must not report writing site-links.json');
    assert.ok(fs.existsSync(path.join(out, SECTION, 'index.html')), 'control: the --out build ran');
    assert.strictEqual(fs.statSync(tracked).mtimeMs, before, 'site-links.json was rewritten by an --out build');
  } finally {
    fs.rmSync(out, { recursive: true, force: true });
  }
});

test('state.js CLI prints the footer line for a matched state page (hooks -> plugins-and-plugin-root only)', () => {
  const out = execFileSync('node', [path.join(__dirname, '..', 'state.js'), 'hooks'], { encoding: 'utf8' });
  const lines = out.split('\n').filter((l) => l.startsWith(LABEL));
  assert.deepStrictEqual(lines, [`${LABEL} https://ccinternals.dev/cowork/plugins-and-plugin-root/?ref=skill`]);
});
